// Pure HTML5 Audio Bell Chime + Web Audio API Dual-Engine
export const BELL_AUDIO_DATA = "data:audio/wav;base64,";

let globalAudio = null;

// Initialize and unlock audio on first user touch/click anywhere on page
export function unlockAudio() {
    try {
        if (!globalAudio) {
            globalAudio = new Audio(BELL_AUDIO_DATA);
            globalAudio.volume = 1.0;
            globalAudio.preload = 'auto';
        }
    } catch (e) {
        console.warn('Audio unlock error:', e);
    }
}

// Play crisp loud hotel service bell sound
export function playOrderBellSound() {
    try {
        unlockAudio();
        if (globalAudio) {
            globalAudio.currentTime = 0;
            globalAudio.volume = 1.0;
            const promise = globalAudio.play();
            if (promise !== undefined) {
                promise.catch(err => {
                    console.warn('HTML5 Audio play prevented, triggering WebAudio fallback:', err);
                    playWebAudioFallback();
                });
            }
            return;
        }
    } catch (e) {
        console.warn('Audio play exception:', e);
    }
    playWebAudioFallback();
}

// Web Audio API pure bell chime fallback
function playWebAudioFallback() {
    try {
        const AudioContextClass = window.AudioContext || window.webkitAudioContext;
        if (!AudioContextClass) return;
        const ctx = new AudioContextClass();
        if (ctx.state === 'suspended') {
            ctx.resume();
        }
        const now = ctx.currentTime;
        const chime = (freq, t, dur, vol = 0.55) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, t);
            gain.gain.setValueAtTime(0.001, t);
            gain.gain.exponentialRampToValueAtTime(vol, t + 0.015);
            gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start(t);
            osc.stop(t + dur);

            const overtone = ctx.createOscillator();
            const gainO = ctx.createGain();
            overtone.type = 'triangle';
            overtone.frequency.setValueAtTime(freq * 2.756, t);
            gainO.gain.setValueAtTime(vol * 0.35, t);
            gainO.gain.exponentialRampToValueAtTime(0.0001, t + dur * 0.6);
            overtone.connect(gainO);
            gainO.connect(ctx.destination);
            overtone.start(t);
            overtone.stop(t + dur);
        };
        chime(1318.51, now, 0.9, 0.55);        // E6
        chime(1760.00, now + 0.16, 1.4, 0.65); // A6
    } catch (err) {
        console.warn('WebAudio fallback error:', err);
    }
}
